class Solution {
  public int nthMagicalNumber(int n, int a, int b) {
    long mod = 1_000_000_007L, l = 1, r = (long) n * Math.min(a, b), lcm = (long) a / gcd(a, b) * b;
    while (l < r) {
      long m = (l + r) >>> 1;
      if (m / a + m / b - m / lcm >= n) r = m;
      else l = m + 1;
    }
    return (int) (l % mod);
  }

  private long gcd(long a, long b) {
    while (b != 0) {
      long t = a % b;
      a = b;
      b = t;
    }
    return a;
  }
}
